import freya,json
sid="84d4bbbe-c7f5-4d9f-b862-d3157cd7aa9c"
its=freya.api("GET",f"/api/v2/simulations/{sid}/iterations")
it=(its.get('iterations') or its.get('data'))[0]
for r in freya.get_iteration(sid,it['id'])['runs']:
  c=freya.get_call(r.get('call_id') or r.get('callId')); print('====')
  for m in c['messages']:
    if m['role']=='system' and ('create_promise' in m['message'] or 'add_note' in m['message']) and 'function_call' in m['message']:
      d=json.loads(m['message']); print(d['event'], json.dumps(d.get('args',{}).get('body') or d.get('result'))[:300])
    elif m['role'] in('assistant','user') and 'negotiate'==m.get('nodeId'): print(m['role'][:1],':',m['message'][:160])
EOF
